import{_ as d,b as a,e,a7 as r}from"./chunks/framework.CFO60l-h.js";const u=JSON.parse('{"title":"课程外必修学分","description":"人大本科生课程外 8 类必修学分：思政实践、形势与政策、劳动、志愿、讲座、职业、研究训练、心理。","frontmatter":{"title":"课程外必修学分","description":"人大本科生课程外 8 类必修学分：思政实践、形势与政策、劳动、志愿、讲座、职业、研究训练、心理。","type":"program-noncourse","tags":["培养方案","学分","非课程"],"updated":"2026-11-07T00:00:00.000Z"},"headers":[],"relativePath":"programs/non-course.md","filePath":"programs/non-course.md","lastUpdated":null}'),l={name:"programs/non-course.md"};function i(o,t,n,s,h,c){return a(),e("div",null,[...t[0]||(t[0]=[r('<h1 id="课程外必修学分" tabindex="-1">课程外必修学分 <a class="header-anchor" href="#课程外必修学分" aria-label="Permalink to &quot;课程外必修学分&quot;">​</a></h1><blockquote><p>人大本科生除了课程，还有 8 类“非课程修读方式”的必修学分，合计约 <strong>13–14 学分</strong>。这些学分大多靠自主申报 + 平台记录，错过窗口很难补。</p></blockquote><h2 id="_8-类学分一览" tabindex="-1">8 类学分一览 <a class="header-anchor" href="#_8-类学分一览" aria-label="Permalink to &quot;8 类学分一览&quot;">​</a></h2><table tabindex="0"><thead><tr><th>模块</th><th style="text-align:right;">学分</th><th>关键要求</th><th>年级差异</th></tr></thead><tbody><tr><td>思政实践课</td><td style="text-align:right;">2</td><td>参加认定项目并结项；时长累计 ≥3 天；P/F</td><td>25/24/23 级与 22 级文件不同</td></tr><tr><td>形势与政策</td><td style="text-align:right;">2</td><td>讲座课 + 研讨实践课各 32 学时；两类积分各 80；结课论文</td><td>各年级基本一致</td></tr><tr><td>劳动教育</td><td style="text-align:right;">1</td><td>理论 + 实践；23/24/25 级 8+24 学时；22 级 10+22</td><td>22 级不同</td></tr><tr><td>志愿服务</td><td style="text-align:right;">2</td><td>24/25 级：≥24 小时且 ≥8 次；22/23 级：≥8 项</td><td>22/23 与 24/25 不同</td></tr><tr><td>科学与人文素养讲座</td><td style="text-align:right;">最多 2</td><td>打卡积分；每 24 学时 1 学分；大四春季前四周申请</td><td>25 级起改名</td></tr><tr><td>职业生涯教育</td><td style="text-align:right;">1</td><td>25 级 38 学时；23/24 级 16 学时；P/F</td><td>22 级为职业规划课</td></tr><tr><td>研究训练</td><td style="text-align:right;">2</td><td>求是学术/大创/竞赛/论文/课题组报告等；不得与思政实践重复</td><td>22 级名称不同</td></tr><tr><td>心理健康教育</td><td style="text-align:right;">22/23 级 1；24/25 级 2</td><td>课程 + 实践活动；23 级另需 20 学时</td><td>年级差异大</td></tr></tbody></table><h2 id="三个最容易错过的点" tabindex="-1">三个最容易错过的点 <a class="header-anchor" href="#三个最容易错过的点" aria-label="Permalink to &quot;三个最容易错过的点&quot;">​</a></h2><ol><li><strong>形势与政策积分</strong>：讲座课和研讨实践课各 80 分，截止大四下学期 4 月底；不要拖到大四。</li><li><strong>科学与人文素养讲座</strong>：大四春季前四周申请，过时不能补。</li><li><strong>研究训练</strong>：不能与思政实践课重复认定；材料要留好（立项/结项/获奖/报告）。</li></ol><h2 id="申报平台" tabindex="-1">申报平台 <a class="header-anchor" href="#申报平台" aria-label="Permalink to &quot;申报平台&quot;">​</a></h2><ul><li>本科教学一体化信息平台</li><li>学务中心</li><li>志愿北京</li><li>智慧职业发展中心</li><li>“RUC 朋小辈”公众号（心理健康实践）</li></ul><h2 id="来源与提醒" tabindex="-1">来源与提醒 <a class="header-anchor" href="#来源与提醒" aria-label="Permalink to &quot;来源与提醒&quot;">​</a></h2><ul><li>来源：学院“RUC新闻一家人”公众号《学时扫盲！快快收藏这份实用指南！》（2026-03-24）整理。</li><li>具体认定细则、时间窗口以当年教务处/学院通知为准。</li><li>本页只做提醒，不作为学分认定依据。</li></ul><div class="tip custom-block"><p class="custom-block-title">怎么用</p><p>把这张表复制到自己的备忘录，每学期末对照一次：哪一项还没开始、哪一项材料没留、哪一项快截止。</p></div>',11)])])}const p=d(l,[["render",i]]);export{u as __pageData,p as default};
